import pandas as pd
import numpy as np


def Decay_Exp(x: pd.DataFrame, d: int) -> pd.DataFrame:
    return x.ewm(span=d, adjust=False).mean()


def Decay_Linear(x: pd.DataFrame, d: int) -> pd.DataFrame:
    weights = np.arange(1, d + 1)
    weights = weights / weights.sum()
    result = x.rolling(window=d).apply(lambda y: (y * weights).sum(), raw=True)
    return result


def Mul(x: pd.DataFrame, y: pd.DataFrame) -> pd.DataFrame:
    result = x * y
    return result


def TS_Return(x: pd.DataFrame, d: int) -> pd.DataFrame:
    return x.pct_change(d)


def signal_exponential_liquidity_adjusted_momentum(Close: pd.DataFrame, Volume: pd.DataFrame) -> pd.DataFrame:
    """Exponential liquidity adjusted momentum"""
    return Mul(TS_Return(Close, 5), Decay_Exp(Decay_Linear(Volume, 5), 5))

def signal_openinterest_enhanced_volume_momentum(Close: pd.DataFrame, Volume: pd.DataFrame, Open_Interest: pd.DataFrame) -> pd.DataFrame:
    """Open interest enhanced volume momentum"""
    return Mul(TS_Return(Close, 5), Mul(Decay_Exp(Volume, 5), TS_Return(Open_Interest, 5)))
